import{_ as e,o as s,c as i,a3 as t}from"./chunks/framework.B9qR_F1m.js";const k=JSON.parse('{"title":"Recipe packs: ripeat tap","description":"","frontmatter":{},"headers":[],"relativePath":"taps.md","filePath":"taps.md"}'),n={name:"taps.md"};function o(p,a,d,h,r,l){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="recipe-packs-ripeat-tap" tabindex="-1">Recipe packs: <code>ripeat tap</code> <a class="header-anchor" href="#recipe-packs-ripeat-tap" aria-label="Permalink to &quot;Recipe packs: \`ripeat tap\`&quot;">​</a></h1><p>A <strong>tap</strong> is a GitHub repository of recipes that someone maintains: a team&#39;s approved tools, a community collection. You add it once, it is pinned to one commit, and its recipes then work with <code>ripeat install</code> like any other. ripeat does not run a server or own a catalog; a pack is just a repository you chose.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme/dev-tools</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # show what is in it, ask, pin it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.org/pack.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # a pack on any static host, pinned by SHA-256</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                               # the packs you have, their commit, how many recipes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-tools</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # the recipes of one pack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # look for newer commits; show exactly what changes; ask</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-tools</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # forget it and delete its recipes</span></span></code></pre></div><h2 id="what-a-pack-looks-like" tabindex="-1">What a pack looks like <a class="header-anchor" href="#what-a-pack-looks-like" aria-label="Permalink to &quot;What a pack looks like&quot;">​</a></h2><p>A repository with a <code>recipes/</code> folder at its top, one <code>name.yaml</code> per recipe, in the ordinary recipe format (<a href="./recipes">Recipes</a>). The file name must match the recipe&#39;s <code>name</code>. Sub-folders and other files are ignored. A pack may hold at most 200 recipes of at most 64 KB each.</p><h2 id="a-pack-at-an-https-address" tabindex="-1">A pack at an https address <a class="header-anchor" href="#a-pack-at-an-https-address" aria-label="Permalink to &quot;A pack at an https address&quot;">​</a></h2><p>Any static host (GitLab, Codeberg, your own site) can serve a pack as <strong>one YAML file</strong>, the pack index:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ripeat_pack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">acme-web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # optional: the default name for the pack</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">recipes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lazygit</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lazygit --version</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    platforms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      linux</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">apt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lazygit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>ripeat tap add https://example.org/pack.yaml [--sha256 hex] [--as name]</code> downloads it (https only, redirects to http refused, at most 512 KB, at most 200 recipes), prints its SHA-256, shows each recipe and asks, like any pack. The SHA-256 of the file is the pin, shown by <code>ripeat tap</code> where a commit would be. If the owner of the pack publishes the SHA-256, pass it as <code>--sha256</code> and the add stops when the file differs. <code>ripeat tap update</code> downloads the file again and, when its SHA-256 changed, shows the recipes added, changed and removed and asks. Every rule below applies unchanged; <code>--ref</code> does not apply to an address.</p><h2 id="adding-one" tabindex="-1">Adding one <a class="header-anchor" href="#adding-one" aria-label="Permalink to &quot;Adding one&quot;">​</a></h2><p><code>ripeat tap add owner/repo [--ref branch-or-tag] [--as name] [--allow-shell]</code> downloads the pack at the commit the branch (default: the repository&#39;s default branch) points to <strong>now</strong>, checks every recipe, and shows you the result before anything is saved:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>acme/dev-tools at commit 0123456 (main). It holds 3 recipe files:</span></span>
<span class="line"><span>  git              not loaded: a built-in recipe has this name, and a pack cannot replace it</span></span>
<span class="line"><span>  lazygit          brew            risk LOW</span></span>
<span class="line"><span>  shelly           not loaded: it runs a shell command, which a pack may only do if you add it with --allow-shell</span></span>
<span class="line"><span>Add the pack &quot;dev-tools&quot; (pinned to 0123456)? [y/N]</span></span></code></pre></div><p>There is <strong>no <code>--yes</code></strong>, and without a terminal it refuses: adding a pack changes which recipes ripeat trusts, so only a person answers. An administrator policy with <code>deny_taps: true</code> (<a href="./admin-policy">Administrator policy</a>) forbids adding or updating packs and hides the recipes of packs already added.</p><h2 id="what-a-pack-can-and-cannot-do" tabindex="-1">What a pack can and cannot do <a class="header-anchor" href="#what-a-pack-can-and-cannot-do" aria-label="Permalink to &quot;What a pack can and cannot do&quot;">​</a></h2><ul><li><strong>Strictly checked.</strong> Each recipe must parse (unknown keys are errors) and pass the same checks as <code>ripeat validate</code>. One that does not is listed as &quot;not loaded&quot; with the reason, and the others still load.</li><li><strong>Plain package names.</strong> A <code>package</code> must be plain names (no spaces-then-options such as <code>x -o ...</code>), because the names become arguments of <code>apt</code>, <code>brew</code> and the rest. This applies to every recipe, not only a pack&#39;s.</li><li><strong>Plain probes only.</strong> ripeat runs a recipe&#39;s <code>check</code> and <code>version</code> commands through the shell every time it plans, to see whether a tool is already installed, so even <code>ripeat plan</code> would run whatever a pack put there. A pack&#39;s <code>check</code> and <code>version</code> may therefore only be a tool&#39;s own name with flags (<code>lazygit --version</code>) or a package manager&#39;s list or info command (<code>brew list --formula lazygit</code>, <code>winget list --id Git.Git --exact</code>, <code>dpkg -s x</code>, <code>command -v x</code>, <code>test -d &lt;path&gt;</code>). No <code>;</code>, <code>&amp;</code>, <code>|</code>, <code>&lt;</code>, <code>&gt;</code>, <code>$</code>, backticks or parentheses, and no other program. <code>tap add</code> and <code>tap update</code> <strong>show each recipe&#39;s check command</strong>, and the rule is applied again every time recipes are loaded. Adding the pack with <code>--allow-shell</code> lifts it, together with the shell-recipe rule.</li><li><strong>No shell commands, unless you say so.</strong> A recipe with a <code>shell</code> option is not loaded unless you added the pack with <code>--allow-shell</code>, which prints a warning. An <code>installer</code> recipe marked <code>unsigned: true</code> is never loaded from a pack. Nor is an <code>.exe</code> or <code>.pkg</code> <code>installer</code> (it would run vendor code as administrator on the pack author&#39;s say-so).</li><li><strong>Cannot replace what is yours.</strong> The layers, lowest first: the built-in recipes, then the packs, then your own recipes. A pack <strong>cannot</strong> take a built-in recipe&#39;s name (so a pack cannot swap in its own <code>git</code>), and your own recipe with the same name wins over a pack&#39;s. If two packs carry the same name, the pack that sorts first by name keeps it, and <code>ripeat tap</code> lists the other as not loaded.</li><li><strong>Rated as strictly as your own.</strong> A recipe from a pack counts as one you added: a download, an installer or a shell command in it is rated accordingly (<a href="./assess">Risk and <code>assess</code></a>), and the reason names the pack. <code>ripeat recipes</code> shows its origin as <code>tap:&lt;name&gt;</code>.</li><li><strong>Checked again every time it loads.</strong> The shell and unsigned rules are applied when the recipes are loaded, not only when the pack is added, so a file dropped into the pack&#39;s folder by hand is not loaded either.</li></ul><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>Nothing changes on its own. <code>ripeat tap update [name]</code> fetches the commit the pack&#39;s branch points to now. If it is the one you have, it says so. If not, it shows each recipe that is <strong>added, changed or removed</strong>, with a line-by-line difference for the changed ones, and every recipe that would not be loaded, then asks. On yes, the folder is replaced and the pin moves; on no, the pack stays exactly as it was. Tools already installed from a pack keep working after an update or <code>remove</code>; a recipe that disappears only stops being available for new installs.</p><p>If a recipe from a pack stops working, <code>ripeat recipes check</code> says so and points at the right fix for a pack: <code>ripeat tap update</code>, the pack&#39;s maintainer, or your own recipe with the same name, which wins (<a href="./recipes">Recipes</a>). <code>ripeat add &lt;name&gt; --refresh</code> does not apply to a pack&#39;s recipe.</p><h2 id="where-it-lives" tabindex="-1">Where it lives <a class="header-anchor" href="#where-it-lives" aria-label="Permalink to &quot;Where it lives&quot;">​</a></h2><p><code>$RIPEAT_HOME/taps/&lt;name&gt;/</code> holds the accepted recipes and <code>$RIPEAT_HOME/taps.json</code> records each pack: repository or address, branch, pinned commit and whether shell recipes are allowed. Downloads use the GitHub API (a rate limit applies; <code>GITHUB_TOKEN</code> raises it).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>GitHub repositories (public ones; with <code>GITHUB_TOKEN</code>, private ones you can read) and https addresses of a pack index. There is no signature on a pack: its trust is the commit you saw and approved, which is why updates show a diff.</li><li>The commit is pinned, but ripeat does not verify who wrote it. Add packs from people you trust, and read what <code>tap add</code> shows.</li><li>An assistant connected through <code>ripeat mcp</code> is told never to run <code>ripeat tap add</code> or <code>ripeat tap update</code>.</li></ul>`,22)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
